+import { Hono } from 'hono';
+
+export const logger = async (c, next) => {
+  const start = Date.now();
+  await next();
+  const duration = Date.now() - start;
+  console.log({
+    method: c.req.method,
+    path: c.req.path,
+    status: c.res.status,
+    body: c.req.json(),
+    duration,
+  });
+};
